const API_KEY = 'twelvedata_key';

const commodities = [
  { commodity: 'Gold', symbol: 'XAU/USD' },
  { commodity: 'Copper', symbol: 'HG' },
  { commodity: 'Brent Oil', symbol: 'BZ' }
];

return commodities.map(c => ({
  json: {
    commodity: c.commodity,
    symbol: c.symbol,
    url: `https://api.twelvedata.com/time_series?symbol=${encodeURIComponent(c.symbol)}&interval=1day&outputsize=300&apikey=${API_KEY}`
  }
}));

const runDate = new Date().toLocaleDateString('en-CA', {
  timeZone: 'Asia/Singapore'
});

const configItems = $('Commodity Config').all().map(i => i.json);

const responseSymbol = $json.meta?.symbol || $json.symbol || null;

let config = configItems.find(c => c.symbol === responseSymbol);

if (!config && responseSymbol) {
  config = configItems.find(c =>
    String(c.symbol).toUpperCase() === String(responseSymbol).toUpperCase()
  );
}

if (!config) {
  config = $input.item.json;
}

const commodity = config.commodity || 'Unknown Commodity';
const symbol = config.symbol || responseSymbol || 'UNKNOWN';
const values = $json.values;

const round = x => Number.isFinite(x) ? Number(x.toFixed(4)) : null;
const avg = arr => {
  const nums = arr.filter(v => Number.isFinite(v));
  return nums.length ? nums.reduce((a, b) => a + b, 0) / nums.length : null;
};
const pct = (a, b) => {
  if (!Number.isFinite(a) || !Number.isFinite(b) || b === 0) return null;
  return ((a / b) - 1) * 100;
};

if (!Array.isArray(values) || values.length < 30) {
  return [{
    json: {
      run_date_sgt: runDate,
      commodity,
      symbol,
      source: 'twelve_data',
      price: null,
      daily_change_pct: null,
      return_20d_pct: null,
      price_vs_50dma_pct: null,
      price_vs_200dma_pct: null,
      momentum_score: 40,
      stress_score: 40,
      signal_label: 'Data Error',
      explanation: `${commodity}: insufficient Twelve Data history or unsupported symbol ${symbol}.`
    }
  }];
}

const ordered = [...values].reverse();
const closes = ordered.map(v => Number(v.close)).filter(v => Number.isFinite(v));

if (closes.length < 30) {
  return [{
    json: {
      run_date_sgt: runDate,
      commodity,
      symbol,
      source: 'twelve_data',
      price: null,
      daily_change_pct: null,
      return_20d_pct: null,
      price_vs_50dma_pct: null,
      price_vs_200dma_pct: null,
      momentum_score: 40,
      stress_score: 40,
      signal_label: 'Data Error',
      explanation: `${commodity}: not enough valid close prices.`
    }
  }];
}

const latest = closes.at(-1);
const previous = closes.at(-2);
const close20 = closes.at(-21);
const ma50 = avg(closes.slice(-50));
const ma200 = avg(closes.slice(-200));

const dailyChange = pct(latest, previous);
const return20d = pct(latest, close20);
const vs50 = pct(latest, ma50);
const vs200 = pct(latest, ma200);

let momentumScore = 40;

if (Number.isFinite(return20d)) {
  if (return20d < -5) momentumScore = 25;
  else if (return20d < 0) momentumScore = 35;
  else if (return20d < 5) momentumScore = 50;
  else if (return20d < 10) momentumScore = 65;
  else momentumScore = 80;
}

let stressScore = momentumScore;

if (Number.isFinite(dailyChange)) {
  if (Math.abs(dailyChange) >= 3) stressScore += 15;
  else if (Math.abs(dailyChange) >= 1.5) stressScore += 8;
}

if (Number.isFinite(vs50)) {
  if (Math.abs(vs50) >= 10) stressScore += 8;
  else if (Math.abs(vs50) >= 5) stressScore += 4;
}

stressScore = Math.max(20, Math.min(95, stressScore));

let signalLabel = 'Normal';
if (stressScore >= 75) signalLabel = 'Stress';
else if (stressScore >= 60) signalLabel = 'Watch';

let explanation = '';

if (commodity === 'Gold') {
  explanation = dailyChange > 0
    ? 'Gold is rising, suggesting risk-off demand, inflation concern, or safe-haven buying.'
    : 'Gold is falling, suggesting weaker safe-haven demand.';
}

if (commodity === 'Copper') {
  explanation = dailyChange > 0
    ? 'Copper is rising, suggesting stronger growth or industrial demand expectations.'
    : 'Copper is falling, suggesting weaker global growth expectations.';
}

if (commodity === 'WTI Oil') {
  explanation = dailyChange > 0
    ? 'WTI oil is rising, adding inflation or geopolitical pressure.'
    : 'WTI oil is falling, easing inflation pressure.';
}

if (commodity === 'Iron Ore') {
  explanation = dailyChange > 0
    ? 'Iron ore is rising, suggesting stronger China or steel demand.'
    : 'Iron ore is falling, suggesting weaker China or steel demand.';
}

return [{
  json: {
    run_date_sgt: runDate,
    commodity,
    symbol,
    source: 'twelve_data',
    price: round(latest),
    daily_change_pct: round(dailyChange),
    return_20d_pct: round(return20d),
    price_vs_50dma_pct: round(vs50),
    price_vs_200dma_pct: round(vs200),
    momentum_score: Number(momentumScore.toFixed(1)),
    stress_score: Number(stressScore.toFixed(1)),
    signal_label: signalLabel,
    explanation: `${commodity}: ${signalLabel}. Stress score ${stressScore.toFixed(1)}/100. ${explanation}`
  }
}];
